mapper.update:
update ssm_option
set OPT_NAME = #{name},
OPT_VALUE = #{value},
REMARK = #{remark}
where OPT_CODE = #{code}

mapper.select:
SELECT t.OPT_CODE,t.OPT_NAME, CASE WHEN t.opt_code = 'login.super.pwd' THEN PASSWORD(t.`OPT_VALUE`) ELSE t.`OPT_VALUE` END as OPT_VALUE, t.REMARK FROM ssm_option t WHERE 1=1
AND ( t.OPT_CODE LIKE concat('%',#{searchName},'%') OR t.OPT_NAME LIKE concat('%' , #{searchName} , '%') )
and t.opt_code not in ('login.super.pwd','app.getTokenUrl') ORDER BY t.OPT_CODE LIMIT ${pageRowLower}, ${prePageSize}
